package main

import (
	"fmt"
	"os/exec"
	"runtime"
	"time"
)

// TTPResult captures the outcome of a single technique execution
type TTPResult struct {
	TechniqueID string        // e.g. "T1082"
	Name        string        // Human-readable technique name
	Success     bool          // Did it execute without error?
	Output      string        // Captured stdout/stderr
	Duration    time.Duration // How long it took
	Timestamp   time.Time     // When it ran
}

// TTPFunc is the signature every technique implementation must satisfy
type TTPFunc func() TTPResult

// Registry maps ATT&CK technique IDs to their execution functions
var Registry = map[string]TTPFunc{
	"T1082": techniqueSystemInfoDiscovery,  // System Information Discovery
	"T1057": techniqueProcessDiscovery,     // Process Discovery
	"T1016": techniqueNetworkConfig,        // System Network Configuration Discovery
}

// techniqueSystemInfoDiscovery implements T1082 — runs OS-native info commands
func techniqueSystemInfoDiscovery() TTPResult {
	start := time.Now()
	cmd := "uname -a"                        // Linux; swap for "systeminfo" on Windows
	if runtime.GOOS == "windows" {
		cmd = "systeminfo"
	}
	out, err := exec.Command("sh", "-c", cmd).CombinedOutput() // Capture stdout+stderr
	return TTPResult{
		TechniqueID: "T1082",
		Name:        "System Information Discovery",
		Success:     err == nil,
		Output:      string(out),
		Duration:    time.Since(start),
		Timestamp:   time.Now(),
	}
}

func main() {
	fmt.Println("[*] ATT&CK Engine initialised — registry has", len(Registry), "techniques")
}

package main

import (
	"fmt"
	"sync"
)

// Dispatch runs a list of technique IDs concurrently and returns all results
func Dispatch(ids []string) []TTPResult {
	results := make(chan TTPResult, len(ids)) // Buffered channel — one slot per technique
	var wg sync.WaitGroup

	for _, id := range ids {
		fn, ok := Registry[id]               // Look up the technique in the registry
		if !ok {
			fmt.Printf("[-] Unknown technique: %s — skipping\n", id)
			continue
		}
		wg.Add(1)                            // Increment counter before launching goroutine
		go func(f TTPFunc, techniqueID string) {
			defer wg.Done()                  // Decrement when goroutine exits
			fmt.Printf("[*] Executing %s\n", techniqueID)
			results <- f()                   // Execute and send result to channel
		}(fn, id)
	}

	wg.Wait()        // Block until every goroutine calls wg.Done()
	close(results)   // Safe to close — all writers are done

	// Drain the channel into a slice
	var out []TTPResult
	for r := range results {
		out = append(out, r)
	}
	return out
}

func main() {
	results := Dispatch([]string{"T1082", "T1057", "T1016"})
	for _, r := range results {
		fmt.Printf("[%s] %s | success=%v | duration=%s\n",
			r.TechniqueID, r.Name, r.Success, r.Duration)
	}
}

