package main

import (
	"encoding/json"
	"fmt"
	"os"
	"time"
)

// Stage represents one tactic phase in the attack chain
type Stage struct {
	Tactic        string   // ATT&CK tactic label, e.g. "TA0003 Persistence"
	Techniques    []string // Technique IDs to execute in this stage
	StopOnFailure bool     // Abort the scenario if any technique in this stage fails
}

// Scenario is the full attack plan
type Scenario struct {
	Name    string  // e.g. "APT29 Simulation"
	Author  string
	Target  string  // Description of the target environment
	Stages  []Stage
}

// Report is the structured output of a completed scenario run
type Report struct {
	Scenario  Scenario              // Original plan
	Results   map[string]TTPResult  // technique ID -> result
	Started   time.Time
	Finished  time.Time
	Succeeded int
	Failed    int
}

// Run executes a Scenario and returns a populated Report
func Run(s Scenario) Report {
	report := Report{
		Scenario: s,
		Results:  make(map[string]TTPResult),
		Started:  time.Now(),
	}

	for _, stage := range s.Stages {
		fmt.Printf("\n[STAGE] %s\n", stage.Tactic)
		stageResults := Dispatch(stage.Techniques)  // Concurrent execution from module 3

		stageFailed := false
		for _, r := range stageResults {
			report.Results[r.TechniqueID] = r
			if r.Success {
				report.Succeeded++
			} else {
				report.Failed++
				stageFailed = true
			}
		}

		if stage.StopOnFailure && stageFailed {
			fmt.Println("[-] Stage failed and StopOnFailure=true — aborting scenario")
			break  // Abort the rest of the attack chain
		}
	}

	report.Finished = time.Now()
	return report
}

// WriteReport serialises the report to a JSON file
func WriteReport(r Report, path string) error {
	data, err := json.MarshalIndent(r, "", "  ")  // Pretty-printed JSON
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

