package main

import (
	"fmt"
	"log"
)

func main() {
	// Define the simulation scenario — a simplified APT29-style chain
	scenario := Scenario{
		Name:   "APT29 Purple Team Exercise",
		Author: "purple-team@corp.local",
		Target: "corp.local — Windows Server 2022 test host",
		Stages: []Stage{
			{
				Tactic:        "TA0007 Discovery",
				Techniques:    []string{"T1082", "T1057", "T1016"}, // Run these concurrently
				StopOnFailure: false,  // Discovery failures are non-critical
			},
			{
				Tactic:        "TA0003 Persistence",
				Techniques:    []string{"T1053"},  // Scheduled task creation
				StopOnFailure: true,   // Can't continue without persistence
			},
			{
				Tactic:        "TA0010 Exfiltration",
				Techniques:    []string{"T1041"}, // Exfil over C2 channel
				StopOnFailure: true,
			},
		},
	}

	fmt.Println("[*] Breach Simulation Engine starting")
	fmt.Printf("[*] Scenario: %s\n", scenario.Name)

	report := Run(scenario)  // Execute the full attack chain

	// Write machine-readable report for SIEM ingestion
	if err := WriteReport(report, "/tmp/breach_report.json"); err != nil {
		log.Fatalf("[-] Failed to write report: %v", err)
	}

	// Human-readable summary to stdout
	fmt.Printf("\n[REPORT] %s\n", report.Scenario.Name)
	fmt.Printf("  Started:   %s\n", report.Started.Format("2006-01-02 15:04:05"))
	fmt.Printf("  Finished:  %s\n", report.Finished.Format("2006-01-02 15:04:05"))
	fmt.Printf("  Succeeded: %d\n", report.Succeeded)
	fmt.Printf("  Failed:    %d\n", report.Failed)
	fmt.Println("[+] Full report written to /tmp/breach_report.json")
}

# Minimal protocol parser using conditionals
# Simulates parsing a simple TLV (Type-Length-Value) binary protocol

def parse_tlv(data: bytes) -> dict:
    """Parse a TLV frame: 1 byte type, 1 byte length, N bytes value."""
    if len(data) < 2:              # Guard: not enough bytes for header
        return {"error": "frame too short"}

    msg_type = data[0]             # First byte: message type
    msg_len  = data[1]             # Second byte: payload length

    if len(data) < 2 + msg_len:   # Guard: payload claims more bytes than we have
        return {"error": "truncated payload"}

    payload = data[2:2 + msg_len]  # Slice exactly msg_len bytes

    # Dispatch on message type — elif chain is the idiomatic switch statement
    if msg_type == 0x01:
        return {"type": "PING", "payload": payload}
    elif msg_type == 0x02:
        return {"type": "CMD", "payload": payload.decode("utf-8", errors="replace")}
    elif msg_type == 0xFF:
        return {"type": "BEACON", "payload": payload.hex()}  # Hex-encode opaque data
    else:
        return {"type": "UNKNOWN", "raw_type": hex(msg_type), "payload": payload}

# Test it
frame = b"\x02\x06whoami"          # Type=CMD, Length=6, Value="whoami"
result = parse_tlv(frame)
print(result)                      # {'type': 'CMD', 'payload': 'whoami'}
